#include<stdio.h>
int main()
{
	char a[5];
	int i,c;
	for(i=0;i<5;i++)
	{
		scanf("%c",&a[i]);
		if(a[i]=='\n')
			break;
		c=i+1;
	}
	printf("%d\n",c);
	for(i=0;i<c;i++)
	{
		printf("%c",a[i]);
		if(i!=c-1)
			printf(" ");
		else
			printf("\n");
	}
	for(i=c-1;i>=0;i--)
	{
		printf("%c",a[i]);
	}
	printf("\n");
	return 0;
}

