#include<stdio.h>
int main()
{
	int a,b,max,min,c,d,temp,t;
	scanf("%d%d",&a,&b);
	c=a,d=b;
	for(;;)
	{
		if(a<b)
			temp=a,a=b,b=temp;
		if(a%b==0)
		{
			max=b;
			break;
		}
		else
		t=a%b,a=b,b=t;
	}
	min=(c*d)/max;
	printf("%d %d\n",max,min);
	return 0;
}

