using namespace std;
int  gcd(int x,int y)
{
	int temp;
	if(x<y)  {temp=x;x=y;y=temp;}
	if(y==0) return x;
	gcd(y,x%y);
}
int go(int n,int m)
{
	return (n/gcd(m,n)*m);
}
int main()
{
	//ifstream cin("aaa.txt");
	int i,j,n,m;
	cin>>n>>m;
	cout<<gcd(n,m)<<" "<<go(n,m)<<endl;


return 0;
}

var
  n,m:longint;
function gcd(a,b:longint):longint;
var r:longint;
begin
  r:=a mod b;
  r:=a mod b;
  while r<>0 do
  begin
    a:=b;
    b:=r;
    r:=a mod b;
  end;
  gcd:=b;
end;
begin
  readln(n,m);
  writeln(gcd(n,m),' ',n*m div gcd(n,m));
end.

