var
  num : array[0..10000] of integer;
  n,i : longint;

begin

  readln(n);
  for i := n downto 1 do
    num[i] := 2*i;
    for i := n downto 1 do
  begin
    if num[i] >= 10 then
    begin
      num[i-1] := num[i] div 10 + num[i-1];
      num[i] := num[i] mod 10;
    end;
  end;
  for i := 0 to n do
  begin
    if (i>0) then
      write(num[i])
    else if num[i] <> 0 then write(num[i]);
    end;
  writeln;

end.

