#include <stdio.h>
#include<string.h>
void judge(int a)
{
    int i,s=0;
    for(i=1; i<a; i++)
    {
        if(a%i==0)
            s=s+i;
    }
    if(s==a)
    {
        printf("%d its factors are",a);
        for(i=1; i<a; i++)
        {
            if(a%i==0)
                printf(" %d",i);
        }
        printf(" \n");
    }
    return;
}
int main()
{
    int n,i,j;
    scanf("%d",&n);
    for(i=2; i<=n; i++)
    {
        judge(i);
    }
    return 0;
}

var
  n,i,j,s:longint;
begin
  readln(n);
  for i:=1 to n do
  begin
    s:=0;
    for j:=1 to i-1 do
    if i mod j=0 then s:=s+j;
    if s=i then begin
    write(i,' its factors are ');
    for j:=1 to i-1 do
    if i mod j=0 then write(j,' ');
    writeln;
    end;
  end;
end.

