	{
		f[0]=1;f[1]=2;
	  sum=0;
	for(i=1;i<=n;i++)
	{ 
		if(i>1)
		  f[i]=f[i-2]+f[i-1];
		sum+=f[i]/f[i-1];
	}
     printf("%.2lf\n",sum);
	}
	return 0;
}

